          "pontibus et magnō iūncta est celeberrima Circō",
          "āreā, quae positō dē bove nōmen habet.",
          "hāc ibi lūce ferunt Mātūtae sacra parentī",
          "scēptriferās Servī templa dedisse manūs.",
          "quae dea sit, quārē famulās ā līmine templī",
          "arceat (arcet enim) lībaque tosta petat,",
          "Bacche racēmiferōs hedera distīnctē capillōs,",
          "sī domus illa tua est, dērigē vātis opus.",
          "ārserat obsequiō Semēlē Iovis: accipit Īnō",
          "tē, puer, et summa sēdula nūtrit ope.",
          "intumuit Iūnō, raptum quod paelice nātum",
          "ēducet: at sanguis ille sorōris erat.",
          "hinc agitur furiīs Athamās et imāgine falsā,",
          "tūque cadis patriā, parvē Learche, manū;",
          "maesta Learchēās māter tumulāverat umbrās",
          "et dederat miserīs omnia iūsta rogīs.",
          "haec quoque, fūnestōs ut erat laniāta capillōs,",
          "prōsilit et cūnīs tē, Melicerta, rapit.",
          "est spatiō contracta brevī, freta bīna repellit,",
          "ūnāque pulsātur, terrā, duābus aquīs:",
          "hūc venit īnsānīs nātum complexā lacertīs,",
          "et sēcum celsō mittit in altā iugō.",
          "excipit inlaesōs Panopē centumque sorōrēs,",
          "et placidō lāpsū per sua rēgna ferunt.",
          "nōndum Leucothea, nōndum puer ille Palaemōn",
          "verticibus dēnsī Thybridīs ōra tenent.",
          "lūcus erat, dubium Semelae Stimulaene vocētur;",
          "maenadas Ausoniās incoluisse ferunt:",
