          "quōs ignōrat adhūc, invocat illa deōs:",
          "'dīque virīque locī, miserae succurrite mātrī.'",
          "clāmor Aventīnī saxa propinqua ferit.",
          "adpulerat rīpae vaccās Oetaeus Hibērās;",
          "audit, et ad vōcem concitus urget iter:",
          "Herculis adventū quae vim modo ferre parābant",
